INSERT INTO arrival_prediction_observation (
raw_observation_id, vehicle_run_observation_id, boarding_stop_id, expected_at, min_expected_at, max_expected_at,
remaining_stops, source, confidence, observed_at, received_at
) VALUES (
#{rawObservationId}, #{vehicleRunObservationId}, #{boardingStopId}, #{expectedAt}, #{minExpectedAt}, #{maxExpectedAt},
#{remainingStops}, #{source}, #{confidence}, #{observedAt}, #{receivedAt}
) RETURNING id

mapper.delete:
DELETE FROM arrival_prediction_observation
WHERE id IN (
    SELECT id
    FROM arrival_prediction_observation
    WHERE received_at  <  #{receivedBefore}
    ORDER BY received_at ASC, id ASC
    LIMIT #{limit}
)
